 UPDATE lessons SET assessment_policy='{"version":"n5-assessment-v3","chapter":9,"title":"Bab 9 — Bepergian","selection":"all","objectives":[{"id":"goal1","canDo":"Memilih arah perjalanan dan verba berdasarkan posisi pembicara."},{"id":"goal2","canDo":"Memahami sarana, asal, dan tujuan perjalanan."},{"id":"goal3","canDo":"Memahami pertanyaan waktu, tujuan, serta teman perjalanan."}],"boundary":{"grammar":["へ 行きます／来ます／帰ります","で＋交通","から〜まで","いつ／どこへ／だれと"],"notes":"Format N5 bertahap; isi Jepang mulai Bab 10, petunjuk Jepang penuh Bab 15. Materi kumulatif sampai bab ini. Pembahasan Indonesia sesudah submit."},"transferTask":{"prompt":"Latihan lisan opsional di luar nilai: gunakan informasi dari salah satu bacaan untuk menjelaskan situasi dengan pola bab ini.","rubric":["Informasi sesuai stimulus.","Pola yang dipelajari digunakan sesuai makna.","Jawaban singkat yang setara dan benar dapat diterima."]},"format":"jlpt-n5","passingScorePct":70,"categoryMinimumPct":50,"minimumObjectiveCorrect":1,"questionsPerForm":24}'::jsonb,content='24 soal persiapan JLPT N5 sesuai materi sampai bab ini. Seluruh soal tampil: 6 aksara/kosakata, 10 tata bahasa, 4 membaca, 4 listening. Termasuk susunan ★ dan pilihan listening yang dibacakan. Audio boleh diputar ulang untuk latihan. Petunjuk Indonesia dikurangi bertahap. Pembahasan dan transkrip muncul setelah submit. Nilai lulus kelas 70%, tiap kategori minimal 50%, dan minimal satu jawaban benar per tujuan; ini bukan skala nilai resmi JLPT.',questions_per_attempt=24,updated_at=now() WHERE id=target;
END;
$jlpt$;

DO $jlpt$
DECLARE target uuid; matches int; scene jsonb;
BEGIN
 SELECT count(*),(array_agg(l.id))[1] INTO matches,target FROM lessons l
 JOIN modules m ON m.id=l.module_id JOIN courses c ON c.id=m.course_id
 WHERE c.slug='n5' AND l.type='quiz' AND l.slug LIKE 'assignment-bab-10-%'
 AND m.title ~* '^BAB\s*10\s*[:：]';
 IF matches<>1 THEN RAISE EXCEPTION '172: missing/ambiguous Bab 10 assignment'; END IF;
 IF EXISTS(SELECT 1 FROM n5_assessment_backup_172 WHERE lesson_id=target) THEN RETURN; END IF;
 IF (SELECT assessment_policy->>'version' FROM lessons WHERE id=target) IS DISTINCT FROM 'n5-assessment-v2'
 THEN RAISE EXCEPTION '172: expected v2 bank for Bab 10'; END IF;
 SELECT id,jsonb_build_object('assessment_policy',assessment_policy,'content',content,'questions_per_attempt',questions_per_attempt) FROM lessons WHERE id=target;
