 INSERT INTO quiz_questions(lesson_id,id,question,question_type,question_category,section_number,section_label,section_instruction,passage,audio_script,image_url,explanation,sort_order,assessment_meta,audio_scene) VALUES(target,'c60e125f-4595-37be-af9e-38128fb0e520','へやで みんなで べんきょうします。ぜんぶで なんにんですか。','multiple_choice','reading',9,'ぶんしょう','ぶんしょうを よんで、こたえて ください。<details><summary>Petunjuk</summary>Gunakan informasi dalam keseluruhan bacaan.</details>','きょうは ともだちと にほんごを べんきょうします。わたしの へやに ともだちが さんにん きます。わたしも いっしょに べんきょうします。へやに いすは みっつ あります。となりの へやに いすが ひとつ あります。つくえの うえに ほんが よんさつ あります。ノートも よんさつ あります。えんぴつは さんぼん あります。かばんの なかにも えんぴつが いっぽん あります。みんなで ごぜん じゅうじから べんきょうします。',NULL,NULL,'Tiga teman ditambah penulis sendiri menjadi empat.',18,'{"version":"n5-assessment-v3","form":"A","key":"b11-a-jlpt-18","objective":"goal2","itemType":"medium_reading","distractorReasons":["Tiga teman ditambah penulis sendiri menjadi empat.","“さんにん” tidak sesuai konteks. Tiga teman ditambah penulis sendiri menjadi empat.","“ふたり” tidak sesuai konteks. Tiga teman ditambah penulis sendiri menjadi empat.","“ごにん” tidak sesuai konteks. Tiga teman ditambah penulis sendiri menjadi empat."]}'::jsonb,NULL);
