 INSERT INTO quiz_questions(lesson_id,id,question,question_type,question_category,section_number,section_label,section_instruction,passage,audio_script,image_url,explanation,sort_order,assessment_meta,audio_scene) VALUES(target,'b4f66c92-3d36-3d71-ac71-b646ff9917e8','きのう なにを しましたか。','multiple_choice','reading',9,'ぶんしょう','ぶんしょうを よんで、こたえて ください。<details><summary>Petunjuk</summary>Gunakan informasi dalam keseluruhan bacaan.</details>','きのうは びょうきだった。がっこうへ いかなかった。うちで やすんだ。ほんも よまなかった。きょうは げんきだ。あしたは がっこうへ いく。あしたは テストが ある。えんぴつを もって いかなければ ならない。じしょは もって いかなくてもいい。テストは くじからだ。はちじはんに がっこうへ いく。テストで ともだちと はなしてはいけない。きょうの よるは うちで べんきょうする。テレビは みない。',NULL,NULL,'Penulis beristirahat di rumah kemarin.',18,'{"version":"n5-assessment-v3","form":"A","key":"b14-a-jlpt-18","objective":"goal1","itemType":"medium_reading","distractorReasons":["“ともだちと べんきょうしました” tidak sesuai konteks. Penulis beristirahat di rumah kemarin.","Penulis beristirahat di rumah kemarin.","“がっこうで テストを しました” tidak sesuai konteks. Penulis beristirahat di rumah kemarin.","“ほんを よみました” tidak sesuai konteks. Penulis beristirahat di rumah kemarin."]}'::jsonb,NULL);
