 INSERT INTO quiz_questions(lesson_id,id,question,question_type,question_category,section_number,section_label,section_instruction,passage,audio_script,image_url,explanation,sort_order,assessment_meta,audio_scene) VALUES(target,'d29dc7f5-9ba4-35c9-a5c2-789b8c43f0c9','アンナさんについて ただしい ものは どれですか。','multiple_choice','reading',9,'ぶんしょう','ぶんしょうを よんで、こたえて ください。','わたしの しゅみは おんがくです。ピアノが できます。まいにち うちで ピアノを ひきます。にほんの おんがくが すきです。ともだちの アンナも おんがくが すきです。アンナは ギターが できます。ピアノは できません。どようびは いっしょに おんがくを ききます。ハディも きます。ハディは テニスが とても じょうずです。おんがくも すきです。ピアノも ギターも できません。わたしたちは にほんごの クラスの ともだちです。にちようびは ハディと おんがくを ききます。ハディは にほんの おんがくが すきです。アンナは えいごの おんがくも すきです。',NULL,NULL,'Anna bisa gitar dan tidak bisa piano.',18,'{"version":"n5-assessment-v3","form":"A","key":"b17-a-jlpt-18","objective":"goal2","itemType":"medium_reading","distractorReasons":["“おんがくが きらいです。” tidak sesuai konteks. Anna bisa gitar dan tidak bisa piano.","“テニスが とても じょうずです。” tidak sesuai konteks. Anna bisa gitar dan tidak bisa piano.","Anna bisa gitar dan tidak bisa piano.","“ピアノが できます。” tidak sesuai konteks. Anna bisa gitar dan tidak bisa piano."]}'::jsonb,NULL);
