 INSERT INTO quiz_questions(lesson_id,id,question,question_type,question_category,section_number,section_label,section_instruction,passage,audio_script,image_url,explanation,sort_order,assessment_meta,audio_scene) VALUES(target,'8a6620f8-fc6d-32c1-8e5a-f2b85696ccdd','この ひとは どの かばんに しましたか。','multiple_choice','reading',9,'ぶんしょう','ぶんしょうを よんで、こたえて ください。','きのう みせで みっつの かばんを みました。あかい かばんは 1000えん、くろい かばんは 800えん、しろい かばんは 1200えんでした。くろい かばんが いちばん やすかったです。あかい かばんは くろい かばんより おおきかったです。しろい かばんは いちばん かるかったです。わたしは かるい かばんが すきです。しろい かばんに しました。きょう がっこうへ もって いきます。ほんと ノートを かばんの なかに いれます。あかい かばんは すこし おもかったです。くろい かばんも しろい かばんより おもかったです。わたしの かばんは まえは くろかったです。',NULL,NULL,'Penulis memilih putih karena paling ringan.',18,'{"version":"n5-assessment-v3","form":"A","key":"b18-a-jlpt-18","objective":"goal1","itemType":"medium_reading","distractorReasons":["“どれも かいませんでした” tidak sesuai konteks. Penulis memilih putih karena paling ringan.","Penulis memilih putih karena paling ringan.","“あかい かばん” tidak sesuai konteks. Penulis memilih putih karena paling ringan.","“くろい かばん” tidak sesuai konteks. Penulis memilih putih karena paling ringan."]}'::jsonb,NULL);
