 INSERT INTO quiz_questions(lesson_id,id,question,question_type,question_category,section_number,section_label,section_instruction,passage,audio_script,image_url,explanation,sort_order,assessment_meta,audio_scene) VALUES(target,'6ccf0787-df3c-326b-91f5-24602fd8e254','この ひとについて ただしい ものは どれですか。','multiple_choice','reading',8,'みじかい ぶんしょう','ぶんしょうを よんで、こたえて ください。','わたしは にほんへ いったことが あります。きょねん ともだちと いきました。すしを たべました。とても おいしかったです。でも、なっとうは たべたことが ありません。',NULL,NULL,'Penulis pernah makan sushi dan belum pernah natto.',17,'{"version":"n5-assessment-v3","form":"A","key":"b20-a-jlpt-17","objective":"goal1","itemType":"short_reading","distractorReasons":["Penulis pernah makan sushi dan belum pernah natto.","“にほんへ いったことが ありません。” tidak sesuai konteks. Penulis pernah makan sushi dan belum pernah natto.","“なっとうを たべたことが あります。” tidak sesuai konteks. Penulis pernah makan sushi dan belum pernah natto.","“きょねん ひとりで にほんへ いきました。” tidak sesuai konteks. Penulis pernah makan sushi dan belum pernah natto."]}'::jsonb,NULL);
