 INSERT INTO quiz_questions(lesson_id,id,question,question_type,question_category,section_number,section_label,section_instruction,passage,audio_script,image_url,explanation,sort_order,assessment_meta,audio_scene) VALUES(target,'56acd1a2-7ff6-3e3a-a5e3-16b32f20231f','こうえんへ いかなかったのは どうしてですか。','multiple_choice','reading',9,'ぶんしょう','ぶんしょうを よんで、こたえて ください。','わたしは きょねん にほんへ いきました。ともだちの アンナさんと いっしょに いきました。とうきょうで すしを たべました。すしは まえにも たべたことが ありましたが、にほんでは はじめてでした。とても おいしかったです。それから、みせで かばんを かいました。きれいでしたが、すこし たかかったです。つぎの ひは あめでしたから、こうえんへは いきませんでした。ホテルで ほんを よみました。らいねんも にほんへ いきたいです。とうきょうは とても にぎやかでした。でんしゃは べんりでしたが、ひとが たくさん いました。つぎは しずかな まちへも いく つもりです。',NULL,NULL,'Teks menyebut hujan sebagai alasan tidak ke taman.',18,'{"version":"n5-assessment-v3","form":"A","key":"b20-a-jlpt-18","objective":"goal2","itemType":"medium_reading","distractorReasons":["“かばんが たかかったですから。” tidak sesuai konteks. Teks menyebut hujan sebagai alasan tidak ke taman.","“すしが おいしかったですから。” tidak sesuai konteks. Teks menyebut hujan sebagai alasan tidak ke taman.","“ほんを かいましたから。” tidak sesuai konteks. Teks menyebut hujan sebagai alasan tidak ke taman.","Teks menyebut hujan sebagai alasan tidak ke taman."]}'::jsonb,NULL);
